        cancelTest();
        cancelTest(); // second call should cancel the first pending timer
        setTimeout(() => {
            assert.strictEqual(fired, false, 'Second call should cancel the first pending call');

            console.log('all tests passed');
        }, 30);
    }, 30);
}, 30);

